                    ['q' => 'ما المداخل البيداغوجية الثلاثة المعروضة لبناء منهاج التعليم الابتدائي في مادة التكوين المرجعية للموسم2021–2022؟', 'c' => ['القيم والكفايات والتربية على الاختيار', 'القيم والتراكم الكمي للمعرفة والتربية على الاختيار', 'القيم والكفايات والتربية على إعادة الإدماج', 'القيم والأهداف وحدها والتربية على الاختيار'], 'a' => 0, 'e' => 'يجمع التصور بين القيم وتنمية القدرة على تعبئة الموارد والتربية على اتخاذ قرار واع. هذه مداخل متكاملة في المرجع المذكور، وليست طرائق متنافسة يلزم اختيار واحدة منها وإلغاء البقية؛ ولا تعني إلغاء الأهداف أو المضامين.'],
                    // YassineCurriculum source Q912.
                    ['q' => 'في تصنيف عام شائع لأسس بناء المناهج، أي مجموعة تربط رؤية المجتمع بطبيعة المعرفة وخصائص المتعلم والسياق الاجتماعي والاقتصادي؟', 'c' => ['الأساس الفلسفي والمعرفي والنفسي والاجتماعي الاقتصادي', 'الأساس الفلسفي والمعرفي والمادي بدلا من النفسي والاجتماعي الاقتصادي', 'الأساس الفلسفي والاجتماعي والنفسي مع حذف البعد المعرفي', 'الأساس الفلسفي والرمزي والنفسي مع حذف البعد المعرفي'], 'a' => 0, 'e' => 'يتصل الأساس الفلسفي بالمقاصد والقيم، والمعرفي باختيار المعارف وتنظيمها، والنفسي بالتعلم والنمو، والاجتماعي بحاجات المجتمع وسياقه. قد تدمج الأدبيات الأبعاد الاقتصادية ضمن السياق الاجتماعي أو تفصلها؛ هذا تصنيف تفسيري عام لا قائمة رسمية وحيدة لكل منهاج مغربي.'],
                    // YassineCurriculum source Q916.
                    ['q' => 'أي مجموعة من مجالات الاختيارات المنهاجية تقابل: المرجع القيمي، وبناء القدرة على الفعل، وما يدرّس، وكيف تنظم الدراسة؟', 'c' => ['القيم وتنمية الكفايات والمضامين وتنظيم الدراسة', 'القيم والمؤسسات والمضامين وتنظيم الدراسة', 'القيم والكفايات والمضامين والأهداف', 'القيم والكفايات والأهداف وتنظيم الدراسة'], 'a' => 0, 'e' => 'تميز هذه المجالات بين المرجع القيمي وما ينمى من كفايات والمضامين المختارة وكيفية تنظيم الدراسة. لا يحصر ذكرها جميع اختيارات المنهاج في أربعة عناصر فقط؛ يعرض المرجع أيضا مواصفات المتعلم والتربية على الاختيار، وتبقى الأهداف ضرورية في التخطيط.'],
                    // YassineProgrammeObjectives source Q924.
