                    // YassineProgrammeObjectives source Q925.
                    ['q' => 'عند عرض البرنامج الدراسي من حيث تنظيم إنجازه عبر الزمن، ما الذي ينبغي أن يتضح فيه؟', 'c' => ['تسلسل الدروس والأنشطة وتوزيعها خلال مدة محددة', 'الاكتفاء بفلسفة المنظومة دون بيان مراحل الإنجاز', 'جمع جميع مكونات المنهاج دون تحديد أي تدرج', 'ذكر الغايات العامة وحدها دون ترتيب العمل'], 'a' => 0, 'e' => 'يبين هذا الجانب من البرنامج تتابع العمل وتوزيعه زمنيا بما يخدم الأهداف. البرنامج التعليمي أوسع من جدول حصص مجرد؛ قد يحدد المحتوى والأنشطة والطرائق والنتائج المنتظرة، وتختلف حدود المصطلح بحسب المرجع والسياق.'],
                    // YassineProgrammeObjectives source Q928.
                    ['q' => 'أي مقاربة يصف صورتها التقليدية درس يكتفي فيه المدرس بإملاء المضامين ويطلب من المتعلمين حفظها واسترجاعها؟', 'c' => ['المقاربة بالأهداف لمجرد وجود أي درس', 'بيداغوجيا الأهداف بوصفها مرادفا لكل إملاء', 'المقاربة بالمضامين في صورتها التلقينية', 'المقاربة بالكفايات من خلال حل وضعية مركبة'], 'a' => 2, 'e' => 'تغلب على هذه الصورة أولوية نقل المحتوى واستظهاره، مع نشاط محدود للمتعلم. الوصف مقيد بالممارسة التلقينية المذكورة؛ لا يعني أن تعلم المضامين غير ضروري، أو أن كل درس يحتوي معرفة هو بالضرورة تلقيني.'],
                    // YassineProgrammeObjectives source Q934.
                    ['q' => 'أي تصنيف اشتهر بدليله الأول المخصص للأهداف في المجال المعرفي؟', 'c' => ['تصنيف واطسون', 'تصنيف سيمبسون للمجال النفسحركي', 'تصنيف كراثوول وزملائه للمجال الوجداني', 'تصنيف بلوم وزملائه للمجال المعرفي'], 'a' => 3, 'e' => 'يتناول الدليل الأول لبلوم وزملائه الأهداف المعرفية، مثل المعرفة والفهم والتحليل. يختلف هذا التحديد عن المجال الوجداني والنفسحركي، ولا يعني أن عمل المجموعة التربوي اقتصر على مجال واحد في جميع منشوراتها اللاحقة.'],
                    // YassineProgrammeObjectives source Q935.
                    ['q' => 'أي تصنيف من الآتي خصص لتنظيم الأهداف المرتبطة بالأداء النفسحركي؟', 'c' => ['تصنيف واطسون', 'تصنيف سيمبسون', 'تصنيف كراثوول للمجال الوجداني', 'تصنيف بلوم الأصلي للمجال المعرفي'], 'a' => 1, 'e' => 'ينظم عمل سيمبسون أهداف الأداء النفسحركي، حيث يتطلب الإنجاز تنسيقا وممارسة ومهارة حركية. لا يقتصر هذا المجال على حركة آلية منعزلة؛ قد تتداخل في المهمة أبعاد معرفية ووجدانية أيضا.'],
                    // YassineProgrammeObjectives source Q936.
                    ['q' => 'بأي مجال يرتبط الدليل الثاني لتصنيف الأهداف الذي أعده كراثوول وبلوم وماسيا؟', 'c' => ['المجال المعرفي وحده', 'المجال النفسحركي عند سيمبسون', 'المجال الوجداني المرتبط بالاتجاهات والقيم والاهتمامات', 'التدبير الإداري للمؤسسة'], 'a' => 2, 'e' => 'يتناول هذا الدليل الأهداف الوجدانية، ومنها الاهتمامات والاتجاهات والقيم. يساعد التمييز بين المجالات في ضبط المقصود من التعلم، دون افتراض أن السلوك الإنساني يقسم في الواقع إلى جوانب منفصلة تماما.'],
                    // YassineProgrammeObjectives source Q942.
                    ['q' => 'في أي سنة صدر الدليل الأول للمجال المعرفي في تصنيف بلوم وزملائه؟', 'c' => ['1956', '1964', '1966', '1975'], 'a' => 0, 'e' => 'صدر الدليل الأول للمجال المعرفي سنة1956. المقصود الإصدار الأصلي، وليس مراجعة أندرسون وكراثوول اللاحقة؛ يفيد تحديد النسخة عند تفسير أسماء المستويات وترتيبها.'],
                    // YassineProgrammeObjectives source Q943.
                    ['q' => 'في أي سنة نشر الدليل الثاني لتصنيف الأهداف، الخاص بالمجال الوجداني، لكراثوول وبلوم وماسيا؟', 'c' => ['1956', '1964', '1966', '1975'], 'a' => 1, 'e' => 'نشر دليل المجال الوجداني سنة1964. يميز هذا التاريخ الإصدار عن دليل المجال المعرفي لسنة1956 وعن تقرير سيمبسون عن المجال النفسحركي لسنة1966؛ فالمراجع ليست إصدارا واحدا متزامنا.'],
                    // YassineProgrammeObjectives source Q944.
                    ['q' => 'ما سنة تقرير سيمبسون The Classification of Educational Objectives, Psychomotor Domain المحفوظ بسجلERICرقمED010368؟', 'c' => ['1956', '1964', '1966', '1975'], 'a' => 2, 'e' => 'يسجلERICالتقرير بسنة1966، وهو عن تصنيف الأهداف النفسحركية. تحديد التقرير يزيل الالتباس مع صيغ أو منشورات لاحقة تنسب إلى سيمبسون، فلا يستعمل التاريخ جوابا عاما عن كل إصدار لذلك التصنيف.'],
                ],
            ],
        ];

        DB::transaction(function () use ($subject, $quizzes): void {
            foreach ($quizzes as $quizData) {
                $quiz = Quiz::updateOrCreate(
                    ['subject_id' => $subject->id, 'title' => $quizData['title']],
                    [
                        'owner_id' => null,
                        'description' => $quizData['description'],
                        'duration' => $quizData['duration'],
                        'passing_score' => $quizData['passing_score'],
                        'total_marks' => count($quizData['questions']),
                        'is_active' => true,
                        'difficulty' => 'Beginner',
                    ]
                );
                foreach ($quizData['questions'] as $qIndex => $item) {
                    $question = Question::updateOrCreate(
                        ['quiz_id' => $quiz->id, 'order' => $qIndex + 1],
                        [
                            'question' => $item['q'],
                            'type' => 'multiple_choice',
                            'marks' => 1,
                            'explanation' => $item['e'],
                        ]
                    );
                    foreach ($item['c'] as $cIndex => $text) {
                        Choice::updateOrCreate(
                            ['question_id' => $question->id, 'order' => $cIndex + 1],
                            ['choice_text' => $text, 'is_correct' => $cIndex === $item['a']]
                        );
                    }
                    $question->choices()->where('order', '>', count($item['c']))->delete();
                }
            }
        });
    }
}
